func firstMissingPositive(nums []int) int {
	size := len(nums)
	for i := 0; i < size; i++ {
		// 先判断这个数字是不是索引，然后判断这个数字是不是放在了正确的地方
		for nums[i] >= 1 && nums[i] <= size && nums[i] != nums[nums[i]-1] {
			nums[i], nums[nums[i]-1] = nums[nums[i]-1], nums[i]
		}
	}
	for i := 0; i < size; i++ {
		if i+1 != nums[i] {
			return i + 1
		}
	}
	return size + 1
}
